/**
 * Client-side bridge: runs inside the app page (dev build) and exposes
 * capture control on a well-known global so an out-of-process driver
 * (Playwright adapter, and later the vite-plugin WS collector) can operate
 * the same channels `captureArtifact` uses in-process.
 *
 * This module must be bundled WITH the app — it needs the app's own
 * `@solidjs/signals` instance. Import it from your dev entry (or let the
 * vite plugin inject it) and call `installDiagnosticsBridge()`.
 */
import { OBSERVE, flush } from "@solidjs/signals";
import { attribution as engine, costs, feedback, why } from "@solidjs/signals/attribution";
import { captureRecords } from "./records.js";
export const BRIDGE_GLOBAL = "__SOLID_DIAGNOSTICS__";
/**
 * Force a value through the same constraints as a page boundary: drops
 * functions, cycles, and host objects so `page.evaluate` transfer can never
 * fail after a capture succeeded.
 */
function toSerializable(value) {
    const seen = new WeakSet();
    return JSON.parse(JSON.stringify(value, (_key, entry) => {
        if (typeof entry === "function" || typeof entry === "symbol")
            return undefined;
        if (typeof entry === "bigint")
            return String(entry);
        if (typeof entry === "object" && entry !== null) {
            if (seen.has(entry))
                return undefined;
            seen.add(entry);
        }
        return entry;
    }));
}
export function installDiagnosticsBridge(target = globalThis) {
    if (!OBSERVE) {
        throw new Error("@solidjs/diagnostics/browser requires a development or observe build of @solidjs/signals: " +
            "the OBSERVE export is undefined in production builds.");
    }
    let session = null;
    const bridge = {
        begin(options = {}) {
            if (session) {
                throw new Error("Diagnostics bridge capture already active; call end() first.");
            }
            const attributionOption = options.attribution ?? true;
            const useAttribution = attributionOption !== false;
            const capture = OBSERVE.diagnostics.capture();
            // The session's own hold on the shared engine (see `capture.ts`).
            let release;
            if (useAttribution) {
                const opts = typeof attributionOption === "object"
                    ? { log: false, ...attributionOption }
                    : { log: false };
                release = engine.enable(opts);
            }
            session = {
                capture,
                records: captureRecords(),
                release,
                startedAt: new Date(),
                start: performance.now()
            };
        },
        end() {
            if (!session) {
                throw new Error("Diagnostics bridge capture not active; call begin() first.");
            }
            const active = session;
            session = null;
            // Drain scheduled work so trailing writes are attributed to the capture.
            flush();
            let attribution = null;
            if (active.release) {
                attribution = {
                    reruns: [...engine.history("rerun")],
                    costs: costs(),
                    holds: [...engine.history("hold")],
                    feedback: feedback()
                };
                active.release();
            }
            const events = active.capture.stop();
            const records = active.records.stop();
            return toSerializable({
                capturedAt: active.startedAt.toISOString(),
                timeOrigin: performance.timeOrigin,
                durationMs: performance.now() - active.start,
                diagnostics: events,
                attribution,
                records
            });
        },
        active() {
            return session !== null;
        },
        whyDidRun(name) {
            requireAttributionSession("whyDidRun");
            // The engine's own query, by name: an out-of-process driver holds no node.
            return toSerializable(why(name));
        },
        costs() {
            requireAttributionSession("costs");
            return toSerializable(costs());
        },
        holds() {
            requireAttributionSession("holds");
            return toSerializable([...engine.history("hold")]);
        },
        feedback() {
            requireAttributionSession("feedback");
            return toSerializable(feedback());
        }
    };
    function requireAttributionSession(caller) {
        if (!session) {
            throw new Error(`Diagnostics bridge ${caller}() requires an open session; call begin() first.`);
        }
        if (!session.release) {
            throw new Error(`Diagnostics bridge ${caller}() requires attribution; the open session was begun with attribution disabled.`);
        }
    }
    target[BRIDGE_GLOBAL] = bridge;
    return bridge;
}
